changeSet.sql:

DROP INDEX IF EXISTS idx_profile_username;

ALTER TABLE profile
    DROP COLUMN IF EXISTS usac_tx_username;

rollback.sql:

ALTER TABLE profile
    ADD COLUMN IF NOT EXISTS usac_tx_username VARCHAR(255);

UPDATE profile p
   SET usac_tx_username = ua.usac_tx_username
  FROM user_account ua
 WHERE ua.usac_cd_id = p.usac_cd_id;

ALTER TABLE profile
    ALTER COLUMN usac_tx_username SET NOT NULL;

CREATE INDEX IF NOT EXISTS idx_profile_username
    ON profile(usac_tx_username);
